"""Kitchen Sink page: CommandLink (Vista-style link buttons), ToolButton (flat buttons: a
toggle, arrows, a drop-down menu) and ButtonBox (the platform's dialog buttons in its
order)."""

from vp6 import *

COLORS = (vpRed, RGB(0, 140, 60), vpBlue)


class pgMoreButtons(Form):
    # region VP6 Designer - generated by the form designer, do not edit
    def InitializeComponent(self):
        self.Caption = 'Link, tool and dialog buttons'
        self.Width = 640
        self.Height = 440
        self.lnkInstall = CommandLink(self, Caption='&Install now', Left=16, Top=16, Width=320,
                                      Height=60, Description='The usual parts, in the usual place',
                                      TabIndex=1)
        self.lnkCustom = CommandLink(self, Caption='&Custom install', Left=16, Top=84, Width=320,
                                     Height=60, Description='Choose the parts, and where they go',
                                     TabIndex=2)
        self.lblLink = Label(self, Caption='Click a link', Left=352, Top=40, Width=272, Height=60,
                             WordWrap=True, TabIndex=3)
        self.tbnBold = ToolButton(self, Caption='B', Left=16, Top=170, Width=33, Height=33,
                                  Checkable=True, FontBold=True, TabIndex=4,
                                  ToolTipText='Checkable: pressed in, the text is bold')
        self.tbnItalic = ToolButton(self, Caption='I', Left=52, Top=170, Width=33, Height=33,
                                    Checkable=True, FontItalic=True, TabIndex=5,
                                    ToolTipText='Checkable: pressed in, the text is italic')
        self.tbnColor = ToolButton(self, Caption='Color', Left=96, Top=170, Width=90, Height=33,
                                   ButtonStyle=2, ArrowType=2, PopupMenu='mnuColors', TabIndex=6,
                                   ToolTipText='A PopupMenu: its arrow drops the colors down')
        self.tbnSmaller = ToolButton(self, Left=200, Top=170, Width=33, Height=33, ArrowType=3,
                                     TabIndex=7, ToolTipText='ArrowType Left: smaller')
        self.tbnBigger = ToolButton(self, Left=236, Top=170, Width=33, Height=33, ArrowType=4,
                                    TabIndex=8, ToolTipText='ArrowType Right: bigger')
        self.lblSample = Label(self, Caption='Tool buttons format this text', Left=16, Top=216,
                               Width=608, Height=60, FontSize=14, TabIndex=9)
        self.lblBox = Label(self,
                            Caption='A ButtonBox: its buttons are in the order this platform puts them',
                            Left=16, Top=330, Width=608, Height=40, WordWrap=True, TabIndex=10)
        self.bbxDialog = ButtonBox(self, Left=16, Top=380, Width=608, Height=40,
                                   Buttons=['OK', 'Cancel', 'Apply', 'Help', '&Reset|reset'],
                                   TabIndex=11)
        self.mnuColors = Menu(self, Caption='Colors', Visible=False)
        self.mnuColor = ControlArray()
        self.mnuColor[0] = Menu(self.mnuColors, Caption='&Red')
        self.mnuColor[1] = Menu(self.mnuColors, Caption='&Green')
        self.mnuColor[2] = Menu(self.mnuColors, Caption='&Blue')
    # endregion

    # --- CommandLink -------------------------------------------------------------------
    def lnkInstall_Click(self):
        self.lblLink.Caption = "Install now: the CommandLink's Click"

    def lnkCustom_Click(self):
        self.lblLink.Caption = f"{self.lnkCustom.Caption.replace('&', '')}: " \
                               f"{self.lnkCustom.Description}"

    # --- ToolButton -----------------------------------------------------------------------
    def tbnBold_Click(self):
        self.lblSample.FontBold = self.tbnBold.Value  # (Checkable: Value is pressed in)

    def tbnItalic_Click(self):
        self.lblSample.FontItalic = self.tbnItalic.Value

    def tbnColor_Click(self):
        self.lblSample.ForeColor = None
        self.lblSample.Caption = "Click: back to the default color (its arrow has colors)"

    def tbnColor_ButtonMenuClick(self, ButtonMenu):
        self.lblSample.ForeColor = COLORS[ButtonMenu.Index]
        self.lblSample.Caption = f"ButtonMenuClick: {ButtonMenu.Caption.replace('&', '')}"

    def mnuColor_Click(self, Index):
        pass  # (the item's own Click fires too)

    def tbnSmaller_Click(self):
        self.lblSample.FontSize = max((self.lblSample.FontSize or 14) - 2, 8)

    def tbnBigger_Click(self):
        self.lblSample.FontSize = min((self.lblSample.FontSize or 14) + 2, 28)

    # --- ButtonBox --------------------------------------------------------------------------
    def bbxDialog_ButtonClick(self, Index):
        caption = self.bbxDialog.ButtonCaption(Index).replace("&", "")
        self.lblBox.Caption = f"ButtonClick: button {Index} ({caption}), its role " \
                              f"{self.bbxDialog.ButtonRole(Index)}"

    def bbxDialog_Accepted(self):
        self.lblBox.Caption += " - Accepted"

    def bbxDialog_Rejected(self):
        self.lblBox.Caption += " - Rejected"


if __name__ == "__main__":
    run(pgMoreButtons)
